import csv, json, os
from collections import defaultdict
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

WS = '/workspace'
OUT = '/workspace/totals.csv'
candidates = []

def json_records(path):
    if path.lower().endswith(('.jsonl', '.ndjson')):
        records = []
        with open(path, encoding='utf-8-sig', errors='ignore') as f:
            for line in f:
                line=line.strip()
                if not line: continue
                try:
                    obj=json.loads(line)
                except Exception:
                    continue
                if isinstance(obj, dict):
                    records.append(obj)
        return records
    with open(path, encoding='utf-8-sig', errors='ignore') as f:
        data=json.load(f)
    if isinstance(data, list):
        return [x for x in data if isinstance(x, dict)]
    if isinstance(data, dict):
        for v in data.values():
            if isinstance(v, list) and v and all(isinstance(x, dict) for x in v):
                return v
    return []

def csv_fields(path):
    try:
        with open(path, encoding='utf-8-sig', errors='ignore') as f:
            sample=f.read(8192)
        if not sample:
            return None
        first=sample.splitlines()[0]
        if 'category' not in first.lower() or 'amount_usd' not in first.lower():
            return None
        delimiter = None
        if '\t' in first and ',' not in first:
            delimiter='\t'
        else:
            try:
                delimiter=csv.Sniffer().sniff(sample, delimiters=',\t;|').delimiter
            except Exception:
                delimiter=','
        return delimiter
    except Exception:
        return None

def json_has_fields(path):
    try:
        if path.lower().endswith(('.jsonl', '.ndjson')):
            with open(path, encoding='utf-8-sig', errors='ignore') as f:
                for line in f:
                    line=line.strip()
                    if not line: continue
                    try:
                        obj=json.loads(line)
                    except Exception:
                        continue
                    if isinstance(obj, dict):
                        keys={str(k).strip().lower() for k in obj.keys()}
                        if 'category' in keys and 'amount_usd' in keys:
                            return True
                    break
            return False
        with open(path, encoding='utf-8-sig', errors='ignore') as f:
            data=json.load(f)
        records = data if isinstance(data, list) else None
        if records is None and isinstance(data, dict):
            for v in data.values():
                if isinstance(v, list) and v and all(isinstance(x, dict) for x in v):
                    records=v
                    break
        if records:
            keys={str(k).strip().lower() for k in records[0].keys()}
            return 'category' in keys and 'amount_usd' in keys
    except Exception:
        pass
    return False

def estimate_rows(path):
    try:
        if path.lower().endswith(('.jsonl', '.ndjson')):
            with open(path, encoding='utf-8-sig', errors='ignore') as f:
                return sum(1 for line in f if line.strip())
        if path.lower().endswith('.json'):
            recs=json_records(path)
            return len(recs)
        with open(path, encoding='utf-8-sig', errors='ignore') as f:
            return sum(1 for _ in f)
    except Exception:
        return 0

for root, dirs, files in os.walk(WS):
    dirs[:] = [d for d in dirs if d not in {'.git', '.venv', 'node_modules'}]
    for name in files:
        p = os.path.join(root, name)
        if os.path.abspath(p) == OUT:
            continue
        if name.lower().endswith(('.csv', '.tsv', '.txt')):
            if csv_fields(p) is not None:
                candidates.append(p)
        elif name.lower().endswith(('.json', '.jsonl', '.ndjson')):
            if json_has_fields(p):
