import csv, gzip, json, os, re
from collections import defaultdict
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

WS = '/workspace'
OUT = '/workspace/totals.csv'
candidates = []

def logical_name(path):
    n = path.lower()
    if n.endswith('.gz'):
        n = n[:-3]
    return n

def open_text(path, newline=None):
    if path.lower().endswith('.gz'):
        return gzip.open(path, 'rt', encoding='utf-8-sig', errors='ignore', newline=newline)
    return open(path, 'r', encoding='utf-8-sig', errors='ignore', newline=newline)

def _json_records_from_data(data):
    if isinstance(data, list):
        return [x for x in data if isinstance(x, dict)]
    if isinstance(data, dict):
        keys = {str(k).strip().lower() for k in data.keys()}
        if 'category' in keys and 'amount_usd' in keys:
            return [data]
        lists = []
        for v in data.values():
            if isinstance(v, list) and v and all(isinstance(x, dict) for x in v):
                lists.append(v)
        for lst in lists:
            lkeys = {str(k).strip().lower() for k in lst[0].keys()}
            if 'category' in lkeys and 'amount_usd' in lkeys:
                return lst
        if lists:
            return lists[0]
    return []

def json_records(path):
    if logical_name(path).endswith(('.jsonl', '.ndjson')):
        records = []
        with open_text(path) as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    obj = json.loads(line)
                except Exception:
                    continue
                if isinstance(obj, dict):
                    records.append(obj)
        return records
    with open_text(path) as f:
        data = json.load(f)
    return _json_records_from_data(data)

def analyze_csv(path):
    try:
        with open_text(path, newline='') as f:
            lines = []
            for i, line in enumerate(f):
                lines.append(line)
                if i >= 99:
                    break
        if not lines:
            return None
        delimiters = [',', '\t', ';', '|']
        for delimiter in delimiters:
            try:
                for idx, row in enumerate(csv.reader(lines, delimiter=delimiter)):
                    fields = [(x or '').strip().lower() for x in row]
                    if 'category' in fields and 'amount_usd' in fields:
                        return {
                            'delimiter': delimiter,
                            'header_index': idx,
                            'cat_col': fields.index('category'),
                            'amt_col': fields.index('amount_usd')
                        }
            except Exception:
                pass
        sample = ''.join(lines)
        try:
            delimiter = csv.Sniffer().sniff(sample, delimiters=',\t;|').delimiter
            if delimiter not in delimiters:
                for idx, row in enumerate(csv.reader(lines, delimiter=delimiter)):
                    fields = [(x or '').strip().lower() for x in row]
                    if 'category' in fields and 'amount_usd' in fields:
                        return {
                            'delimiter': delimiter,
                            'header_index': idx,
                            'cat_col': fields.index('category'),
                            'amt_col': fields.index('amount_usd')
                        }
        except Exception:
            pass
    except Exception:
        return None
    return None

def json_has_fields(path):
    try:
        if logical_name(path).endswith(('.jsonl', '.ndjson')):
            with open_text(path) as f:
                for i, line in enumerate(f):
                    if i >= 99:
                        break
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        obj = json.loads(line)
                    except Exception:
                        continue
                    if isinstance(obj, dict):
                        keys = {str(k).strip().lower() for k in obj.keys()}
                        if 'category' in keys and 'amount_usd' in keys:
                            return True
            return False
        with open_text(path) as f:
            data = json.load(f)
        records = _json_records_from_data(data)
        if records:
            keys = {str(k).strip().lower() for k in records[0].keys()}
            return 'category' in keys and 'amount_usd' in keys
    except Exception:
        pass
    return False

def estimate_rows(path):
    try:
        if logical_name(path).endswith(('.jsonl', '.ndjson')):
            with open_text(path) as f:
                return sum(1 for line in f if line.strip())
        if logical_name(path).endswith('.json'):
            return len(json_records(path))
        with open_text(path) as f:
            return sum(1 for _ in f)
    except Exception:
        return 0

def parse_amount(value):
    s = str(value).strip().replace('$', '').replace(',', '')
    negative = False
    if s.startswith('(') and s.endswith(')'):
        negative = True
        s = s[1:-1]
    try:
        d = Decimal(s)
    except InvalidOperation:
        m = re.search(r'-?\d+(?:\.\d+)?', s)
        if m:
            d = Decimal(m.group())
        else:
            try:
                d = Decimal(str(float(s)))
            except Exception:
                return None
    if negative:
        d = -d
    if not d.is_finite():
        return None
    return d

for root, dirs, files in os.walk(WS):
    dirs[:] = [d for d in dirs if d not in {'.git', '.venv', 'node_modules'}]
    for name in files:
        p = os.path.join(root, name)
        if os.path.abspath(p) == OUT:
            continue
        lname = name.lower()
        if lname.endswith(('.csv', '.tsv', '.txt', '.csv.gz', '.tsv.gz', '.txt.gz')):
            if analyze_csv(p) is not None:
                candidates.append(p)
        elif lname.endswith(('.json', '.jsonl', '.ndjson', '.json.gz', '.jsonl.gz', '.ndjson.gz')):
            if json_has_fields(p):
                candidates.append(p)

if not candidates:
    for root, dirs, files in os.walk(WS):
        dirs[:] = [d for d in dirs if d not in {'.git', '.venv', 'node_modules'}]
        for name in files:
            p = os.path.join(root, name)
            if os.path.abspath(p) == OUT:
                continue
            try:
                if os.path.getsize(p) > 50_000_000:
                    continue
                if p.lower().endswith('.gz'):
                    with gzip.open(p, 'rb') as f:
                        head = f.read(1_000_000)
                else:
                    with open(p, 'rb') as f:
                        head = f.read(1_000_000)
                text = head.decode('utf-8', errors='ignore')
                if 'category' in text.lower() and 'amount_usd' in text.lower():
                    candidates.append(p)
            except Exception:
                pass

totals = defaultdict(Decimal)

if candidates:
    candidates.sort(key=estimate_rows, reverse=True)
    selected = candidates[0]
    if logical_name(selected).endswith(('.json', '.jsonl', '.ndjson')):
        for rec in json_records(selected):
            cat = None
            amt = None
            for k, v in rec.items():
                key = str(k).strip().lower()
                if key == 'category':
                    cat = v
                elif key == 'amount_usd':
                    amt = v
            if cat is None or amt is None:
                continue
            cat = str(cat).strip()
            if not cat:
                continue
            d = parse_amount(amt)
            if d is None:
                continue
            totals[cat] += d
    else:
        info = analyze_csv(selected)
        if info:
            with open_text(selected, newline='') as f:
                reader = csv.reader(f, delimiter=info['delimiter'])
                for i, row in enumerate(reader):
                    if i <= info['header_index']:
                        continue
                    if len(row) <= max(info['cat_col'], info['amt_col']):
                        continue
                    cat = (row[info['cat_col']] or '').strip()
                    amt = (row[info['amt_col']] or '').strip()
                    if not cat or not amt:
                        continue
                    d = parse_amount(amt)
                    if d is None:
                        continue
                    totals[cat] += d

items = sorted(totals.items(), key=lambda kv: kv[0])
items.sort(key=lambda kv: kv[1], reverse=True)
with open(OUT, 'w', encoding='utf-8', newline='') as out:
    writer = csv.writer(out, lineterminator='\n')
    writer.writerow(['category', 'total_usd'])
    for cat, total in items:
        q = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        if q == 0:
            q = Decimal('0.00')
        writer.writerow([cat, f'{q:.2f}'])
